b-outage.text:
[
  {
    "title": "HTTP Flood via Application Layer Exhaustion",
    "description": "An attacker sends a high volume of complex search queries or heavy database-intensive requests to overwhelm the web server's CPU and memory."
  },
  {
    "title": "Slowloris Connection Exhaustion",
    "description": "An attacker opens numerous connections to the storefront and keeps them open by sending partial HTTP requests, exhausting the server's connection pool."
  },
  {
    "title": "Inventory Scraping Bot Attack",
    "description": "Aggressive automated bots crawl product pages and stock levels at high frequency, consuming server resources and slowing response times for legitimate users."
  },
  {
    "title": "Large File Download Request Attack",
    "description": "An attacker repeatedly requests large assets or high-resolution product images to saturate the storefront's outbound bandwidth."
  },
  {
    "title": "Database Query Injection for Resource Exhaustion",
    "description": "An attacker exploits a vulnerable search field to execute computationally expensive SQL queries that lock database tables and prevent legitimate transactions."
  }
]

