[
  {
    "title": "Cross-Site Scripting on Customer Profile Pages",
    "description": "An attacker injects malicious JavaScript into a customer's profile fields to intercept sensitive data when a staff member views the account in the admin console."
  },
  {
    "title": "Insecure Direct Object Reference in Order History",
    "description": "An attacker manipulates order ID parameters in the URL to access and download the personal details and card tokens of other customers."
  },
  {
    "title": "Man-in-the-Middle via Weak TLS Configuration",
    "description": "An attacker intercepts unencrypted or weakly encrypted network traffic between the customer's browser and the web shop to capture personal information."
  },
  {
    "title": "Session Hijacking via XSS on the Storefront",
    "description": "An attacker steals active session cookies from authenticated customers to gain access to their stored shipping addresses and account details."
  },
  {
    "title": "Exploitation of Vulnerable Third-Party Plugin",
    "description": "An attacker leverages a known vulnerability in a third-party shipping or tax calculation plugin to execute code and access the application database."
  }
]
